script.lang:
insert into amp_global_settings(id,settingsName,settingsValue,possibleValues,description, section)
values ((SELECT MAX(id) + 1 FROM amp_global_settings), 'Recreate the views on the next server restart','true','t_Boolean','Recreate the views on the next server restart', 'general');
DROP VIEW IF EXISTS v_amp_organisations;
CREATE OR REPLACE VIEW v_amp_organisations AS
SELECT name AS id, name AS value FROM amp_organisation;

INSERT INTO amp_global_settings(id, settingsName, settingsValue, possiblevalues, description, section)
VALUES ((SELECT MAX(id) + 1 FROM amp_global_settings), 'Internal Ecowas Donor',
(SELECT id FROM v_amp_organisations WHERE value = 'ECOWAS'),
'v_amp_organisations', 'Internal Ecowas Donor', 'funding');
